// A bike of the catalogue, as returned by the API (same fields as the backend)
export type BikeModel = {
  id: string;
  brand: string;
  model: string;
  description: string;
  category: string;
  frameMaterial: string;
  frameSizeCm: number;
  wheelSizeInches: number;
  gearCount: number;
  weightKg: number;
  electric: boolean;
  priceCents: number; // price in cents
};

// Data sent to create a bike: everything except the id (generated by the API)
export type CreateBikeModel = Omit<BikeModel, "id">;

// PATCH is a partial update: only the fields sent are changed
export type UpdateBikeModel = Partial<CreateBikeModel>;

// Describes the response of GET /bikes and types the Axios call
export type BikesPageModel = {
  totalCount: number;
  bikes: BikeModel[];
};